  num_fields: u32,
  num_rows: u32,
  lut_size: u32,        // number of real color LUT entries (<= 256)
  opacity: f32,
  max_count: f32,
  gamma: f32,
  color_mode: u32,      // 0 = index (categorical), 1 = interpolate (continuous value)
  plot_y1: f32,
  plot_y2: f32,
